source='''from collections import Counter, defaultdict


def _period_scores(grid, start=3):
    scores = {}
    for period in range(2, 13):
        score = total = 0
        for row in grid[start:]:
            groups = defaultdict(Counter)
            for col in range(start, len(row)):
                value = row[col]
                if value != 0:
                    groups[col % period][value] += 1
            for counts in groups.values():
                score += max(counts.values())
                total += sum(counts.values())
        scores[period] = (score, total)
    return scores


def transform(grid):
    """Restore erased cells in a framed, horizontally periodic color pattern."""
    height, width = len(grid), len(grid[0])
    scores = _period_scores(grid)
    best_rate = max(score / total for score, total in scores.values() if total)
    period = min(
        p for p, (score, total) in scores.items()
        if total and score / total >= best_rate - 1e-12
    )

    out = [row[:] for row in grid]
    for r in range(height):
        for c in range(width):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                candidates = Counter(
                    grid[r][cc]
                    for cc in range(3, width)
                    if grid[r][cc] != 0 and cc % period == c % period
                )
                if not candidates:
                    candidates = Counter(
                        grid[rr][c]
                        for rr in range(3, height)
                        if grid[rr][c] != 0 and rr % period == r % period
                    )
                out[r][c] = candidates.most_common(1)[0][0]
    return out
